def accessOracle(query, params=None):
    dsn_tns = '10.31.8.21:1521/ORABPI'
    try:
        with oracledb.connect(user='owner_31_bpi_3_0', password='owner31bpi', dsn=dsn_tns) as conn:
            with conn.cursor() as c:
                c.execute(query, params)
                return c.fetchall()
    except oracledb.DatabaseError as e:
        logging.error(f"Database error occurred: {e}")
        return None
    except Exception as e:
        logging.error(f"Error occurred while accessing Oracle: {e}")
        return None



def getlpn_packagereport_batch():
    
    # >>> SQL排序优化：核心改动在这里
    # 1. TUBINFO 和 BAGINFO 都改为按 LPC IN (...) 批量查询，并用 ROW_NUMBER 取每个LPC的最新一条
    # 2. 主查询末尾加上 ORDER BY fs.CLOSE_DT，让数据库直接按资源关闭时间排序
    getlpnQuery = f"""
        SELECT
            DISTINCT (substr( L_SCREENINGRESULT,- 10 )) as LPN 
        FROM
            WC_PACKAGEREPORT
        WHERE
            1 = 1
            AND EVENTTS > TO_TIMESTAMP( '2026-10-12 16:00:00', 'YYYY-MM-DD HH24:MI:SS' )
            AND EVENTTS < TO_TIMESTAMP( '2026-10-13 16:00:00', 'YYYY-MM-DD HH24:MI:SS' )
            AND areaid IN ( 4,5,6,7,8,20,21,22,23,24 )
            AND RESULTTYPE = 'ScreeningResult'
            and L_SCREENINGRESULT like '%UNCLEARED%'
        ORDER BY 1
    """
    return accessOracle(getlpnQuery)

# >>> SQL排序优化：函数改为接收LPC列表，SQL改为IN查询并直接ORDER BY
def packageinfo_batch(lpc_list):
    # 为 IN 子句生成占位符，如 :lpc0, :lpc1, :lpc2
    placeholders = ', '.join([f':lpc{i}' for i in range(len(lpc_list))])
    params = {f'lpc{i}': val for i, val in enumerate(lpc_list)}
    
    # >>> SQL排序优化：核心改动在这里
    # 1. TUBINFO 和 BAGINFO 都改为按 LPC IN (...) 批量查询，并用 ROW_NUMBER 取每个LPC的最新一条
    # 2. 主查询末尾加上 ORDER BY fs.CLOSE_DT，让数据库直接按资源关闭时间排序
    UrgencyPackageQuery = f"""
        with BAGINFO AS (
        SELECT
            LPC,
            REPLACE ( substr( NAME, 1, 7 ), '_', '' ) AS flightnr 
        FROM
            (
            SELECT
                LPC,
                NAME,
                ROW_NUMBER ( ) OVER ( PARTITION BY LPC ORDER BY IDEVENT DESC ) AS rn 
            FROM
                WC_PACKAGEINFO 
            WHERE
                LPC IN ({placeholders} ) 
                and EVENTTS >= TRUNC( SYSDATE ) - 3
                and name is not null
            ) 
        WHERE
            rn = 1 
        )
        select * from BAGINFO
    """
    return accessOracle(UrgencyPackageQuery, params)


